mapper.select:
SELECT id, user_id, token_hash, family_id, expires_at, revoked_at, created_at
FROM refresh_tokens
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE id = #{id}
  AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{revokedAt}
WHERE family_id = #{familyId}
  AND revoked_at IS NULL
